  assign Add_stage4_add_cast_2 = Add_op_stage2_im[33:2];
  assign Add_stage4_add_cast_3 = {{2{Delay3_out1_im_1[31]}}, Delay3_out1_im_1[31:2]};
  assign Add_stage4_add_temp_1 = Add_stage4_add_cast_2 + Add_stage4_add_cast_3;
  assign Add_out1_im = Add_stage4_add_temp_1[25:10];


  always @(posedge clk or negedge rst_n)
    begin : Out1_re_buf_process
      if (rst_n == 1'b0) begin
        Out1_re_buf <= 16'sb0000000000000000;
        Out1_im_buf <= 16'sb0000000000000000;
        Out5_re_buf <= 16'sb0000000000000000;
        Out5_im_buf <= 16'sb0000000000000000;
      end
      else begin
        if (enb) begin
          Out1_re_buf <= Add_out1_re;
          Out1_im_buf <= Add_out1_im;
          Out5_re_buf <= Add_out1_re;
          Out5_im_buf <= Add_out1_im;
        end
      end
  end

  assign Out1_re = Out1_re_buf;
  assign Out1_im = Out1_im_buf;
  assign Out5_re = Out5_re_buf;
  assign Out5_im = Out5_im_buf;

  assign ce_out = enb_1_1_1;

endmodule  // pp_int_x4

